v.text("A", Ax - 0.5, Ay - 0.4, { color: H.colors.accent, size: 13 });
v.text("B", Bx + 0.3, By + 0.4, { color: H.colors.accent, size: 13 });
const dx = Bx - Ax, dy = By - Ay;
const len = Math.hypot(dx, dy) || 1;
const px = -dy / len, py = dx / len;
const ext = 6;
v.line(Mx - px * ext, My - py * ext, Mx + px * ext, My + py * ext, { color: H.colors.warn, width: 3 });
v.dot(Mx, My, { r: 5, fill: H.colors.warn });
